BEGIN;
SELECT set_config('request.jwt.claim.sub','b2f6e43d-ce24-4de2-a770-0548793cc180',true);
SET LOCAL ROLE authenticated;
DO $$DECLARE aid uuid; original uuid; rid uuid; card uuid; bank uuid; pid uuid; original_account uuid; future_purchase public.finance_card_purchases;r public.finance_recurring_expenses;a public.enterprise_finance_accounts;p public.finance_card_purchases; v jsonb; opts jsonb;im date:=(date_trunc('month',current_date)+interval '1 month')::date;BEGIN
 v:=jsonb_build_object('description','Conta inline teste','amount_cents',10000,'due_on',current_date,'kind','payable');
 aid:=public.save_inline_payable(v,NULL,NULL,'{"enabled":false}');original:=aid;
 SELECT * INTO a FROM public.enterprise_finance_accounts WHERE id=aid;
 aid:=public.save_inline_payable(v,aid,a.updated_at,'{"enabled":true,"frequency":"monthly"}');
 IF aid<>original THEN RAISE EXCEPTION 'Conversão substituiu conta original';END IF;
 SELECT * INTO a FROM public.enterprise_finance_accounts WHERE id=aid;rid:=a.recurrence_id;
 IF rid IS NULL OR (SELECT count(*) FROM public.enterprise_finance_accounts WHERE recurrence_id=rid AND occurrence_on=current_date)<>1 THEN RAISE EXCEPTION 'Conta original duplicada';END IF;
 UPDATE public.enterprise_finance_accounts SET settled_on=current_date WHERE id=aid;
 SELECT * INTO a FROM public.enterprise_finance_accounts WHERE id=aid;SELECT * INTO r FROM public.finance_recurring_expenses WHERE id=rid;
 PERFORM public.save_inline_payable(v||jsonb_build_object('amount_cents',20000),aid,a.updated_at,jsonb_build_object('enabled',true,'scope','future','frequency','monthly','rule_updated_at',r.updated_at));
 IF (SELECT amount_cents FROM public.enterprise_finance_accounts WHERE id=aid)<>10000 THEN RAISE EXCEPTION 'Conta paga alterada pela série';END IF;
 SELECT * INTO a FROM public.enterprise_finance_accounts WHERE id=aid;SELECT * INTO r FROM public.finance_recurring_expenses WHERE id=rid;
 PERFORM public.save_inline_payable(v,aid,a.updated_at,jsonb_build_object('enabled',false,'rule_updated_at',r.updated_at));
 IF (SELECT deleted_at FROM public.enterprise_finance_accounts WHERE id=aid) IS NOT NULL OR EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE recurrence_id=rid AND id<>aid AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Parar repetição não preservou conta base ou manteve próximas';END IF;
 v:=jsonb_build_object('description','Conversão histórica rollback','amount_cents',5000,'due_on',(current_date-interval '3 months')::date,'kind','payable');
 aid:=public.save_inline_payable(v,NULL,NULL,'{"enabled":false}');
 SELECT * INTO a FROM public.enterprise_finance_accounts WHERE id=aid;
 PERFORM public.save_inline_payable(v,aid,a.updated_at,'{"enabled":true,"frequency":"monthly"}');
 SELECT recurrence_id INTO rid FROM public.enterprise_finance_accounts WHERE id=aid;
 IF EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE recurrence_id=rid AND id<>aid AND occurrence_on<current_date) THEN RAISE EXCEPTION 'Conversão histórica criou despesas retroativas';END IF;
 INSERT INTO public.finance_bank_accounts(name) VALUES('Banco inline rollback') RETURNING id INTO bank;
 INSERT INTO public.finance_credit_cards(name,closing_day,due_day,bank_account_id) VALUES('Cartão inline rollback',25,5,bank) RETURNING id INTO card;
 v:=jsonb_build_object('card_id',card,'description','Assinatura teste','amount_cents',9900,'purchased_on',current_date,'installments',1,'first_invoice_month',im);
 pid:=public.save_inline_card_purchase(v,NULL,NULL,'{"enabled":false}');SELECT * INTO p FROM public.finance_card_purchases WHERE id=pid;
 SELECT id INTO original_account FROM public.enterprise_finance_accounts WHERE card_purchase_id=pid;
 PERFORM public.save_inline_card_purchase(v,pid,p.updated_at,'{"enabled":true,"frequency":"monthly"}');
 SELECT * INTO p FROM public.finance_card_purchases WHERE id=pid;rid:=p.recurrence_id;
 IF rid IS NULL OR (SELECT count(*) FROM public.finance_card_purchases WHERE recurrence_id=rid AND occurrence_on=current_date)<>1 OR NOT EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE id=original_account AND recurrence_id=rid) THEN RAISE EXCEPTION 'Compra base duplicada/substituída';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.finance_card_purchases WHERE recurrence_id=rid AND purchased_on>current_date) THEN RAISE EXCEPTION 'Próximas compras não geradas';END IF;
 SELECT * INTO future_purchase FROM public.finance_card_purchases WHERE recurrence_id=rid AND purchased_on>current_date ORDER BY purchased_on LIMIT 1;
 PERFORM public.save_inline_card_purchase(v||jsonb_build_object('amount_cents',12345,'purchased_on',future_purchase.purchased_on,'first_invoice_month',future_purchase.first_invoice_month),future_purchase.id,future_purchase.updated_at,'{"enabled":true,"scope":"one","frequency":"monthly"}');
 PERFORM public.sync_finance_recurrences(NULL,rid);
 IF (SELECT amount_cents FROM public.finance_card_purchases WHERE id=future_purchase.id)<>12345 THEN RAISE EXCEPTION 'Ajuste individual no cartão perdido';END IF;
 PERFORM public.settle_card_invoice(card,im,current_date,bank,9900);
 SELECT * INTO p FROM public.finance_card_purchases WHERE id=pid;SELECT * INTO r FROM public.finance_recurring_expenses WHERE id=rid;
 PERFORM public.save_inline_card_purchase(v||jsonb_build_object('amount_cents',11000),pid,p.updated_at,jsonb_build_object('enabled',true,'scope','future','frequency','monthly','rule_updated_at',r.updated_at));
 IF (SELECT amount_cents FROM public.enterprise_finance_accounts WHERE id=original_account)<>9900 THEN RAISE EXCEPTION 'Fatura paga alterada';END IF;
 IF (SELECT amount_cents FROM public.finance_card_purchases WHERE id=future_purchase.id)<>12345 THEN RAISE EXCEPTION 'Série sobrescreveu compra individual';END IF;
 SELECT * INTO p FROM public.finance_card_purchases WHERE id=pid;SELECT * INTO r FROM public.finance_recurring_expenses WHERE id=rid;
 PERFORM public.save_inline_card_purchase(v,pid,p.updated_at,jsonb_build_object('enabled',false,'rule_updated_at',r.updated_at));
 IF EXISTS(SELECT 1 FROM public.enterprise_finance_accounts WHERE recurrence_id=rid AND card_purchase_id<>pid AND deleted_at IS NULL) OR (SELECT deleted_at FROM public.finance_card_purchases WHERE id=pid) IS NOT NULL THEN RAISE EXCEPTION 'Parar cartão perdeu compra base ou manteve próximas';END IF;
END $$;
SELECT set_config('request.jwt.claim.sub','a6fd10de-33d6-45c3-b423-9290dad107ea',true);
DO $$BEGIN BEGIN PERFORM public.save_inline_payable('{}');RAISE EXCEPTION 'Colaborador gravou despesa';EXCEPTION WHEN insufficient_privilege THEN NULL;END;BEGIN PERFORM public.save_inline_card_purchase('{}');RAISE EXCEPTION 'Colaborador gravou compra';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END $$;
RESET ROLE;ROLLBACK;
SELECT 'PASS: repetição no lançamento, conversão sem duplicar, cartão com futuras faturas, ajuste individual, série e baixa preservada, parada e RLS; rollback completo' result;
